fn solve(input: Vec<char>) -> Vec<char> {
    // We know input is non-empty and input[0] is in 'a'..='y'.
    let first = input[0];
    // Compute the successor character ('a' -> 'b', ..., 'y' -> 'z').
    let next_char = std::char::from_u32(first as u32 + 1).unwrap();
    // Return a two‐character Vec: [successor, newline].
    vec![next_char, '\n']
}

